    final salemEmpty = find.descendant(
      of: _cardOf('Salem'),
      matching: find.byIcon(Icons.star_border),
    );

    expect(onyxStars, findsNWidgets(5));
    expect(salemStars, findsOneWidget);
    expect(salemEmpty, findsNWidgets(4));
  });

